// TMP - carga manual S33/S34 (issue #128). Se borra al terminar la carga.
const cfg = $('Set secreto RPC').first().json;
const body = ($('Webhook').first().json.body) || {};
const action = body.action || 'ping';
const db = body.db || cfg.db;

let doPost;
if (typeof $helpers !== 'undefined' && $helpers && $helpers.httpRequest) {
  doPost = (p) => $helpers.httpRequest({ method: 'POST', url: cfg.url + '/jsonrpc', body: p, json: true });
} else {
  doPost = async (p) => {
    const r = await fetch(cfg.url + '/jsonrpc', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(p) });
    return r.json();
  };
}
async function rpc(service, method, args) {
  const res = await doPost({ jsonrpc: '2.0', method: 'call', id: Date.now(), params: { service, method, args } });
  if (res && res.error) {
    const e = res.error;
    throw new Error('RPC: ' + ((e.data && e.data.message) || e.message || JSON.stringify(e)));
  }
  return res.result;
}
const uid = await rpc('common', 'login', [db, cfg.login, cfg.key]);
if (!uid) throw new Error('Login fallo: revisa db/login/ODOO_RPC_KEY (db probado: ' + db + ')');
const kw = (model, method, args, kwargs) => rpc('object', 'execute_kw', [db, uid, cfg.key, model, method, args, kwargs || {}]);

const RUBRO = { ingreso: 1171, mo: 1177, mat: 1176, aldo: 1178, rissia: 1179, diego: 1157, luisangel: 1158, montalvo: 1156, sup: 1159, tec: 1160 };
const ANT_NAME = 'Anticipos y préstamos a empleados';
const out = { action: action, db: db, uid: uid };

if (action === 'ping') {
  const v = await rpc('common', 'version', []);
  out.server_version = v && v.server_version;

} else if (action === 'prereq') {
  // A1 - cuenta de anticipos (plan 14)
  const found = await kw('account.analytic.account', 'search_read', [[['name', '=', ANT_NAME], ['plan_id', '=', 14]]], { fields: ['id', 'name', 'active'], context: { active_test: false } });
  if (found.length) {
    out.a1 = { status: 'ya existia', record: found[0] };
  } else {
    const id = await kw('account.analytic.account', 'create', [{ name: ANT_NAME, plan_id: 14, company_id: 1 }]);
    const rb = await kw('account.analytic.account', 'read', [[id], ['id', 'name', 'active', 'plan_id', 'company_id']]);
    out.a1 = { status: 'creada', record: rb[0] };
  }
  // A2 - budget SO11551 (cuenta 3071)
  const BUD = 'SO11551 - Suministro y Puesta en marcha Quimitec';
  let budId;
  const bfound = await kw('budget.analytic', 'search_read', [[['name', '=', BUD]]], { fields: ['id', 'state'] });
  if (bfound.length) { budId = bfound[0].id; out.a2_header_previo = bfound[0]; }
  else { budId = await kw('budget.analytic', 'create', [{ name: BUD, budget_type: 'both', date_from: '2026-06-09', date_to: '2027-06-09', company_id: 1 }]); }
  const wanted = [[RUBRO.ingreso, 1148745.70], [RUBRO.mo, 0], [RUBRO.mat, 0], [RUBRO.aldo, 0], [RUBRO.rissia, 0], [RUBRO.diego, 0], [RUBRO.luisangel, 0], [RUBRO.montalvo, 0], [RUBRO.sup, 0], [RUBRO.tec, 0]];
  const exist = await kw('budget.line', 'search_read', [[['budget_analytic_id', '=', budId]]], { fields: ['x_plan20_id'] });
  const have = {};
  for (const l of exist) if (l.x_plan20_id) have[l.x_plan20_id[0]] = true;
  const newLines = [];
  for (const w of wanted) if (!have[w[0]]) newLines.push(await kw('budget.line', 'create', [{ budget_analytic_id: budId, account_id: 3071, x_plan20_id: w[0], budget_amount: w[1], date_from: '2026-06-09', date_to: '2027-06-09' }]));
  await kw('budget.analytic', 'write', [[budId], { state: 'confirmed' }]);
  const hdr = await kw('budget.analytic', 'read', [[budId], ['id', 'name', 'state', 'date_from', 'date_to']]);
  out.a2 = { header: hdr[0], lineas_creadas: newLines, lineas_total: await kw('budget.line', 'search_count', [[['budget_analytic_id', '=', budId]]]) };
  // A4 - rubros de comision en budget 412 (SO11832, cuenta 3107)
  const r4 = [RUBRO.aldo, RUBRO.rissia, RUBRO.diego, RUBRO.luisangel, RUBRO.montalvo, RUBRO.sup, RUBRO.tec];
  const ex4 = await kw('budget.line', 'search_read', [[['budget_analytic_id', '=', 412]]], { fields: ['x_plan20_id'] });
  const have4 = {};
  for (const l of ex4) if (l.x_plan20_id) have4[l.x_plan20_id[0]] = true;
  const new4 = [];
  for (const r of r4) if (!have4[r]) new4.push(await kw('budget.line', 'create', [{ budget_analytic_id: 412, account_id: 3107, x_plan20_id: r, budget_amount: 0.0, date_from: '2026-08-17', date_to: '2027-08-17' }]));
  out.a4 = { lineas_creadas: new4, lineas_total_412: await kw('budget.line', 'search_count', [[['budget_analytic_id', '=', 412]]]) };

} else if (action === 'jobs') {
  // A5 - saneamiento de puestos (issue #128)
  const UNARCHIVE = (body.unarchive_jobs || []).concat([16, 22]);
  const jobsPre = await kw('hr.job', 'read', [UNARCHIVE, ['id', 'name', 'active']]);
  const toUn = jobsPre.filter((j) => !j.active).map((j) => j.id);
  if (toUn.length) await kw('hr.job', 'write', [toUn, { active: true }]);
  out.a51 = { antes: jobsPre, desarchivados: toUn };
  // A5.2 - crear puestos nuevos (via body.create_jobs: [{name, emp}])
  out.a52 = [];
  const assigns = [[75, 22], [79, 16], [76, 22], [78, 25], [121, 29]].concat(body.extra || []);
  for (const cj of (body.create_jobs || [])) {
    const ex = await kw('hr.job', 'search_read', [[['name', '=', cj.name]]], { fields: ['id', 'name', 'active'], context: { active_test: false } });
    let jobId;
    if (ex.length) { jobId = ex[0].id; if (!ex[0].active) await kw('hr.job', 'write', [[jobId], { active: true }]); out.a52.push({ name: cj.name, status: 'ya existia', id: jobId }); }
    else { jobId = await kw('hr.job', 'create', [{ name: cj.name }]); out.a52.push({ name: cj.name, status: 'creado', id: jobId }); }
    if (cj.emp) assigns.push([cj.emp, jobId]);
  }
  // A5.3 - escribir job_id (+ job_title coherente; el write directo NO dispara el onchange de la UI)
  const jobIds = assigns.map((a) => a[1]).filter((v, i, arr) => arr.indexOf(v) === i);
  const jobNames = {};
  for (const j of await kw('hr.job', 'read', [jobIds, ['id', 'name']])) jobNames[j.id] = j.name;
  for (const a of assigns) await kw('hr.employee', 'write', [[a[0]], { job_id: a[1], job_title: jobNames[a[1]] }]);
  // Read-back
  const empIds = assigns.map((a) => a[0]);
  out.a53_readback = await kw('hr.employee', 'read', [empIds, ['id', 'name', 'job_id', 'job_title']]);
  out.a51_readback = await kw('hr.job', 'read', [UNARCHIVE, ['id', 'name', 'active']]);

} else if (action === 'canary') {
  const id = await kw('account.analytic.line', 'create', [{ name: 'CM CANARY · cuenta archivada 3071', date: '2026-08-14', amount: -0.01, account_id: 3071, company_id: 1 }]);
  const rb = await kw('account.analytic.line', 'read', [[id], ['id', 'name', 'date', 'amount', 'account_id', 'company_id', 'currency_id']]);
  out.canary = rb[0];

} else if (action === 'canary_delete') {
  const ids = await kw('account.analytic.line', 'search', [[['name', '=like', 'CM CANARY ·%']]]);
  if (ids.length) await kw('account.analytic.line', 'unlink', [ids]);
  out.borradas = ids;
  out.restantes = await kw('account.analytic.line', 'search_count', [[['name', '=like', 'CM CANARY ·%']]]);

} else if (action === 'load_s33') {
  const PFX = 'CM S33/2026 ·';
  const pre = await kw('account.analytic.line', 'search_count', [[['name', '=like', PFX + '%']]]);
  if (pre > 0) throw new Error('Ya existen ' + pre + ' lineas con prefijo "' + PFX + '" - no se carga doble. Usa delete_cm primero si es intencional.');
  const DEST = { SO11507: { x_plan18_id: 1139, company_id: 6 }, SO11551: { account_id: 3071, company_id: 1 }, SO11511: { account_id: 3061, company_id: 1 } };
  const M = [
    ['Mateo Salazar', 75, RUBRO.sup, 82.00, 'SO11507', false],
    ['Felipe Perez', 112, RUBRO.sup, 82.00, 'SO11507', false],
    ['Leonel Cruz', 6, RUBRO.tec, 82.00, 'SO11507', false],
    ['Jose Luis Romero', 79, RUBRO.tec, 84.00, 'SO11507', false],
    ['Luis Angel Garcia', 48, RUBRO.tec, 84.00, 'SO11507', false],
    ['Gibran Solis', 62, RUBRO.tec, 4074.00, 'SO11551', false],
    ['Tomas Vazquez', 131, RUBRO.tec, 4074.00, 'SO11551', false],
    ['Felipe Perez', 112, RUBRO.sup, 4074.00, 'SO11551', false],
    ['Carlos Manzanares', 76, RUBRO.sup, 4074.00, 'SO11551', false],
    ['Felipe Perez', 112, RUBRO.sup, 713.00, 'SO11511', false],
    ['Carlos Manzanares', 76, RUBRO.sup, 713.00, 'SO11511', false],
    ['Jose Luis Romero', 79, RUBRO.tec, 713.00, 'SO11511', true]
  ];
  const ids = [];
  for (const row of M) {
    const n = row[0], e = row[1], r = row[2], amt = row[3], dest = row[4], dnp = row[5];
    const vals = Object.assign({
      name: PFX + ' bono · ' + n + ' · ' + dest + ' · ' + (dnp ? 'SIN-PAGO' : 'J96'),
      date: '2026-08-14', amount: -amt, employee_id: e, x_plan20_id: r
    }, DEST[dest]);
    if (dnp) vals.ref = 'DNP-S33';
    ids.push(await kw('account.analytic.line', 'create', [vals]));
  }
  const rb = await kw('account.analytic.line', 'search_read', [[['name', '=like', PFX + '%']]], { fields: ['id', 'name', 'date', 'amount', 'company_id', 'currency_id'], order: 'id asc' });
  let usd = 0, mxn = 0;
  for (const l of rb) { if (l.company_id && l.company_id[0] === 6) usd += l.amount; else mxn += l.amount; }
  out.creadas = ids.length;
  out.readback_count = rb.length;
  out.sum_usd = Math.round(usd * 100) / 100; out.esperado_usd = -414.00;
  out.sum_mxn = Math.round(mxn * 100) / 100; out.esperado_mxn = -18435.00;
  out.ok = (rb.length === 12 && out.sum_usd === -414.00 && out.sum_mxn === -18435.00);
  out.lineas = rb;

} else if (action === 'load_s34') {
  const PFX = 'CM S34/2026 ·';
  const pre = await kw('account.analytic.line', 'search_count', [[['name', '=like', PFX + '%']]]);
  if (pre > 0) throw new Error('Ya existen ' + pre + ' lineas "' + PFX + '"');
  const ant = await kw('account.analytic.account', 'search_read', [[['name', '=', ANT_NAME], ['plan_id', '=', 14]]], { fields: ['id', 'name'], context: { active_test: false } });
  if (!ant.length) throw new Error('No existe la cuenta de anticipos - corre action=prereq primero');
  await kw('account.analytic.line', 'create', [{ name: PFX + ' anticipo · Leonel Cruz · ANTICIPOS · J96', date: '2026-08-21', amount: -3500.00, x_plan14_id: ant[0].id, company_id: 1, employee_id: 6 }]);
  const rb = await kw('account.analytic.line', 'search_read', [[['name', '=like', PFX + '%']]], { fields: ['id', 'name', 'date', 'amount', 'x_plan14_id', 'employee_id', 'company_id'] });
  out.cuenta_anticipos = ant[0];
  out.readback = rb;
  out.ok = (rb.length === 1 && rb[0].amount === -3500);

} else if (action === 'count') {
  const p = body.prefix;
  if (!p) throw new Error('Falta prefix');
  const rb = await kw('account.analytic.line', 'search_read', [[['name', '=like', p + '%']]], { fields: ['id', 'name', 'date', 'amount', 'company_id'], order: 'id asc' });
  out.count = rb.length;
  out.sum = Math.round(rb.reduce((a, l) => a + l.amount, 0) * 100) / 100;
  out.lineas = rb;

} else if (action === 'delete_cm') {
  const p = body.prefix;
  if (!p || p.indexOf('CM ') !== 0) throw new Error('prefix debe empezar con "CM "');
  const rb = await kw('account.analytic.line', 'search_read', [[['name', '=like', p + '%']]], { fields: ['id', 'name', 'date', 'amount'] });
  if (!body.confirm_ids) {
    out.paso = '1/2 - revisa matches y reenvia el mismo POST agregando confirm_ids';
    out.matches = rb;
  } else {
    const valid = rb.map((l) => l.id);
    const toDel = body.confirm_ids.filter((i) => valid.indexOf(i) >= 0);
    if (toDel.length !== body.confirm_ids.length) throw new Error('Algun confirm_id no esta en el match actual - aborto sin borrar');
    if (toDel.length) await kw('account.analytic.line', 'unlink', [toDel]);
    out.borradas = toDel;
    out.restantes = await kw('account.analytic.line', 'search_count', [[['name', '=like', p + '%']]]);
  }

} else {
  throw new Error('action desconocida: ' + action);
}

return [{ json: out }];
